// Rule-based escalation, checked BEFORE any model is used.
// The LLM never decides escalation: if a keyword appears, the question goes to a human.
const keywords = $('Settings').first().json.escalation_keywords.split(',');

const out = [];
for (const item of $input.all()) {
  const question = item.json.question;
  const lower = question.toLowerCase();
  let matched = '';
  for (const keyword of keywords) {
    if (lower.includes(keyword.trim())) {
      matched = keyword.trim();
      break;
    }
  }
  out.push({
    json: {
      question_id: item.json.question_id,
      category: item.json.category || '',
      question: question,
      matched_keyword: matched,
    },
  });
}
return out;

// Find the 3 most similar articles for every question and decide the route.
const settings = $('Settings').first().json;
const threshold = Number(settings.threshold);

// The index file holds one object; Convert to File may have wrapped it in a list.
let index = $('Extract index').first().json.data;
if (Array.isArray(index)) {
  index = index[0];
}
const articles = index.articles;

// Cosine similarity: 1 = same direction (same meaning), 0 = unrelated.
function cosine(a, b) {
  let dot = 0;
  let normA = 0;
  let normB = 0;
  for (let i = 0; i < a.length; i++) {
    dot = dot + a[i] * b[i];
    normA = normA + a[i] * a[i];
    normB = normB + b[i] * b[i];
  }
  return dot / (Math.sqrt(normA) * Math.sqrt(normB));
}

const systemPrompt =
  'You are the support assistant for Kerbloop, a delivery software. ' +
  'Answer ONLY with information from the articles below. ' +
  'Cite the id of every article you use in square brackets, for example [ADR-001]. ' +
  'Keep the answer short. ' +
  "If the articles do not contain the answer, reply exactly: I don't know";

// n8n keeps item order, so embedding number i belongs to question number i.
const questions = $('Check escalation rules').all();
const embeddings = $input.all();

const out = [];
for (let i = 0; i < questions.length; i++) {
  const q = questions[i].json;
  const vector = embeddings[i].json.embeddings[0];

  // Score every article, then sort from most to least similar.
  const scored = [];
  for (const article of articles) {
    scored.push({ id: article.id, title: article.title, text: article.text, score: cosine(vector, article.embedding) });
  }
  scored.sort(function (x, y) { return y.score - x.score; });
  const top = scored.slice(0, 3);

  // Route: escalation keywords first, then the similarity threshold, else the model answers.
  let route = 'answer';
  if (q.matched_keyword !== '') {
    route = 'escalate';
  } else if (top[0].score < threshold) {
    route = 'dont_know';
  }

  let prompt = '';
  for (const article of top) {
    prompt = prompt + '[' + article.id + '] ' + article.title + '\n' + article.text + '\n\n';
  }
  prompt = prompt + 'Question: ' + q.question;

  out.push({
    json: {
      question_id: q.question_id,
      category: q.category,
      question: q.question,
      matched_keyword: q.matched_keyword,
      route: route,
      top1_id: top[0].id,
      top1_score: Number(top[0].score.toFixed(4)),
      top2_id: top[1].id,
      top2_score: Number(top[1].score.toFixed(4)),
      top3_id: top[2].id,
      top3_score: Number(top[2].score.toFixed(4)),
      system_prompt: systemPrompt,
      prompt: prompt,
    },
  });
}
return out;

// Keep only the questions that the model should answer (route = answer).
const out = [];
for (const item of $input.all()) {
  if (item.json.route === 'answer') {
    out.push(item);
  }
}
return out;

// Combine every question with its final bot answer and write one row per question.
const settings = $('Settings').first().json;
const allQuestions = $('Retrieve top 3').all();
const modelQuestions = $('Only model questions').all();
const modelAnswers = $input.all();

// Model answers come back in the same order as the model questions.
const answerById = {};
for (let i = 0; i < modelQuestions.length; i++) {
  answerById[modelQuestions[i].json.question_id] = modelAnswers[i].json.response.trim();
}

const rows = [];
for (const item of allQuestions) {
  const q = item.json;
  let botAnswer = '';
  if (q.route === 'escalate') {
    botAnswer = 'Escalated to a human agent.';
  } else if (q.route === 'dont_know') {
    botAnswer = "I don't know";
  } else {
    botAnswer = answerById[q.question_id];
  }

  // Article ids the answer cites, for example [FD-002].
  const cited = botAnswer.match(/\b(ADR|TW|FD|DRV|ACC)-\d{3}\b/g) || [];
  const citedUnique = [...new Set(cited)];

  rows.push({
    json: {
      run_id: settings.run_id,
      kb_version: settings.version,
      threshold: settings.threshold,
      question_id: q.question_id,
      category: q.category,
      question: q.question,
      route: q.route,
      matched_keyword: q.matched_keyword,
      top1_id: q.top1_id,
      top1_score: q.top1_score,
      top2_id: q.top2_id,
      top2_score: q.top2_score,
      top3_id: q.top3_id,
      top3_score: q.top3_score,
      bot_answer: botAnswer,
      cited_ids: citedUnique.join(';'),
    },
  });
}
return rows;
